<template>
  <div>
    <div class="container">
      <div style="margin-top: 10px">
        <div
          style="
            display: flex;
            justify-content: space-between;
            align-items: center;
          "
        >
          <q-input
            v-model="searchText"
            placeholder="Search Task"
            dense
            outlined
            style="width: 250px; margin-bottom: 10px"
            @update:model-value="nonComputedfilteredTasks()"
          />
        </div>
        <q-markup-table flat bordered id="task_management_table">
          <thead>
            <tr>
              <template v-for="(col, index) in table_columns" :key="col.name">
                <th
                  v-bind="{} as any"
                  :data-index="index"
                  :draggable="canDragDropColumn(col)"
                  :dropzone="canDragDropColumn(col)"
                  direction="horizontal"
                  @dragstart="onDragStart($event, table_columns, index)"
                  @drop.prevent="handleDrop($event, index)"
                  @dragover.prevent="onDragOver($event, index)"
                  @dragenter.prevent="onDragEnter"
                  @dragleave.prevent="onDragLeave"
                  :style="[
                    col.style || '',
                    { cursor: getIsDragging ? 'pointer' : 'move' },
                  ]"
                >
                  <div :class="col.class || ''">
                    {{ col.label }}
                    <div v-if="col.name !== 'start_now'" class="sort-buttons">
                      <button
                        @click="sortTable(col.sort_order, 'asc')"
                        :class="getSortButtonClass(col.sort_order, 'asc')"
                        class="sort-button"
                      >
                        ▲
                      </button>
                      <button
                        @click="sortTable(col.sort_order, 'desc')"
                        :class="getSortButtonClass(col.sort_order, 'desc')"
                        class="sort-button"
                      >
                        ▼
                      </button>
                    </div>
                  </div>
                </th>
              </template>
            </tr>
          </thead>
        </q-markup-table>
      </div>
      <div class="table-container">
        <q-markup-table flat bordered>
          <tbody>
            <tr v-for="task in displayedTasks" :key="task['Task ID']">
              <template v-for="col in table_columns" :key="col.name">
                <td v-if="col.name == 'task'" style="width: 20%">
                  {{ formateName(task['Task']) }}
                </td>
                <td
                  v-else-if="col.name == 'run_for_last_time'"
                  style="text-align: right; width: 20%"
                >
                  {{ formatDateAccordingToPreference(task['Last Run Time']) }}
                </td>
                <td
                  v-else-if="col.name == 'interval'"
                  style="text-align: right; width: 20%"
                >
                  {{ formateSchedule(task['Schedule']) }}
                </td>
                <td
                  v-else-if="col.name == 'run_next_time'"
                  style="text-align: right; width: 20%"
                >
                  {{ formatDateAccordingToPreference(task['Next Run Time']) }}
                </td>
                <td v-else class="start-button">
                  <q-btn
                    icon="refresh"
                    @click="startTask(task)"
                    style="width: 20%"
                  />
                </td>
              </template>
            </tr>
          </tbody>
        </q-markup-table>
      </div>
      <div
        class="back-white flex justify-end"
        style="margin: 10px; margin-top: 0px"
      >
        <div class="row" style="margin-right: 0">
          <div class="setting-line">
            <span style="margin-top: -0.5px" class="q-py-xs q-mt-xs q-mr-sm"
              >Tasks per Page:</span
            >
            <q-select
              borderless
              dense
              v-model="pagination_size"
              :options="pagination_options"
              @update:model-value="updatePagination"
            />
          </div>
          <q-separator vertical />
          <q-pagination
            v-model="paginationCount"
            color="primary"
            :max="maxpages"
            class="q-py-xs q-mx-md"
            :max-pages="5"
            input
            boundary-links
            @update:model-value="loadData()"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import cronstrue from 'cronstrue';
import { LocalStorage } from 'quasar';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import { importApiService } from 'src/services';
import dragDropColumn from 'src/mixins/dragDropColumn';
export default defineComponent({
  el: '#app',
  components: {},
  mixins: [dateUtils, dragDropColumn],
  data() {
    return {
      paginationCount: ref(1),
      skip: ref(1),
      startfrom: ref(0),
      pageSize: ref(10),
      maxpages: ref(1),
      tasks: ref([] as Array<{ [key: string]: any }>),
      sortColumn: '',
      sortOrder: '',
      refreshIntervalId: null as NodeJS.Timeout | null,
      pagination_size: ref(10),
      pagination_options: ref(['10', '15', '20', '25']),
      displayedTasks: ref([] as Array<{ [key: string]: any }>),
      searchText: ref(''),
      table_columns: [
        {
          label: 'TASK',
          name: 'task',
          sort_order: 'Task',
          class: 'first-header-content',
          style: { width: '20%' },
        },
        {
          label: 'RAN FOR THE LAST TIME',
          name: 'run_for_last_time',
          sort_order: 'Last_Run_Time',
          class: 'middle-header-content',
          style: { width: '20%' },
        },
        {
          label: 'INTERVAL',
          name: 'interval',
          sort_order: 'Schedule',
          class: 'middle-header-content',
          style: { width: '20%' },
        },
        {
          label: 'RUN NEXT TIME',
          name: 'run_next_time',
          sort_order: 'Next_Run_Time',
          class: 'middle-header-content',
          style: { width: '20%' },
        },
        {
          label: 'START NOW',
          name: 'start_now',
          sort_order: '',
          class: 'text-right cursor-default',
        },
      ],
    };
  },
  watch: {
    pagination_size() {
      this.updatePagination();
    },
    paginationCount() {
      this.updateDisplayedTasks();
    },
    tasks() {
      this.updateDisplayedTasks();
    },
  },
  computed: {
    filteredTasks() {
      return this.tasks.filter((task) => {
        let taskName = task['Task'];
        if (typeof taskName === 'string') {
          taskName = task.Task.replaceAll('_', ' ');
          return taskName.toLowerCase().includes(this.searchText.toLowerCase());
        }
        return false;
      });
    },
    sortedTasks() {
      const sortedTasks = [...this.filteredTasks];
      const column = this.sortColumn;
      const sortOrder = this.sortOrder;

      if (column) {
        sortedTasks.sort((a, b) => {
          let aVal: any = a[column];
          let bVal: any = b[column];

          if (typeof aVal === 'string') aVal = aVal.toLowerCase();
          if (typeof bVal === 'string') bVal = bVal.toLowerCase();

          if (sortOrder === 'asc') {
            return aVal > bVal ? 1 : -1;
          } else {
            return aVal < bVal ? 1 : -1;
          }
        });
      }
      return sortedTasks;
    },
  },
  methods: {
    async init() {
      await this.fetchTasks();
      this.startAutoRefresh();
      this.loadData();
      this.maxPages();
    },
    async fetchTasks() {
      try {
        const response = await importApiService.fetchTasksData();
        this.tasks = JSON.parse(response);
        this.updateDisplayedTasks();
        this.maxPages();
      } catch (error) {
        logError('Failed to fetch tasks:', error);
      }
    },
    updateDisplayedTasks() {
      const startIndex = (this.paginationCount - 1) * this.pagination_size;
      const endIndex = startIndex + this.pagination_size;
      this.displayedTasks = this.sortedTasks.slice(startIndex, endIndex);
    },
    updatePagination() {
      this.paginationCount = 1;
      this.maxPages();
      this.updateDisplayedTasks();
    },
    nonComputedfilteredTasks() {
      let temp_task_save = [] as any;
      this.tasks.forEach((task: any) => {
        let taskName = task.Task.replaceAll('_', ' ');
        if (taskName.includes(this.searchText.toLowerCase())) {
          temp_task_save.push(task);
        }
      });
      if (temp_task_save.length > 0) {
        this.displayedTasks = temp_task_save;
      }
      this.maxPages();
    },
    async startTask(task: { [key: string]: any }) {
      try {
        let taskName = task['Task'];
        let org_id = 'Placeholder for org_id';
        await importApiService.startTask(taskName, org_id);
        notify.success(`Task '${this.formateName(task['Task'])}' has been retriggered.`);
      } catch (error) {
        notify.error(`Failed to retrigger task '${this.formateName(task['Task'])}'.`);
        logError(error);
      }
    },
    formateSchedule(strSchedule: string) {
      try {
        let fSymbol = strSchedule.slice(1, 2);
        if (fSymbol === 'c') {
          let mSymbol = strSchedule.slice(11, 12);
          var formattedString = strSchedule.slice(10, -14);
          if (mSymbol === ' ') {
            var newSchedule = cronstrue.toString(formattedString);
            var finalSchedule = newSchedule.replace(
              newSchedule.slice(0, 14),
              ' ',
            );
            var finalSchedule = finalSchedule.replace('e', 'E');
            return finalSchedule;
          } else {
            var finalSchedule = cronstrue.toString(formattedString);
            return finalSchedule;
          }
        } else {
          var finalSchedule = strSchedule.replace(strSchedule.slice(0, 7), '');
          var finalSchedule = finalSchedule.replace(strSchedule.slice(-1), '');
          var finalSchedule = finalSchedule.replace('.00', '');
          return finalSchedule;
        }
      } catch (error) {
        logError('Failed to convert string', error);
        return strSchedule;
      }
    },
    formateName(strName: any) {
      var formattedName: string = strName.replaceAll('_', ' ');
      var formattedName =
        formattedName.charAt(0).toUpperCase() + formattedName.slice(1);
      return formattedName;
    },
    sortTable(column: string, order: string) {
      this.sortColumn = column;
      this.sortOrder = order;
      this.updateDisplayedTasks();
    },
    getSortButtonClass(column: string, order: string) {
      return {
        'active-sort-button':
          this.sortColumn === column && this.sortOrder === order,
        'sort-button': true,
      };
    },
    startAutoRefresh() {
      this.refreshIntervalId = setInterval(() => {
        this.fetchTasks();
      }, 10000);
    },
    loadData() {
      this.startfrom = this.pagination_size * (this.paginationCount - 1);
    },
    maxPages() {
      this.maxpages = Math.ceil(this.sortedTasks.length / this.pagination_size);
    },
    prepareTableColumn() {
      const saved_columns = LocalStorage.getItem(
        'TASK_MANAGEMENT_SETTING_COLUMNS',
      ) as string;
      if (saved_columns) {
        this.table_columns = JSON.parse(saved_columns);
      }
    },
    onDropColumns() {
      LocalStorage.set(
        'TASK_MANAGEMENT_SETTING_COLUMNS',
        JSON.stringify(this.table_columns),
      );
    },
  },
  mounted() {
    this.prepareTableColumn();
    this.init();
    this.initDragDropColumns('task_management_table', 'label', ['start_now']);
    document.addEventListener(
      'task_management_table-column-drop',
      this.onDropColumns,
    );
  },
  unmounted() {
    document.removeEventListener(
      'task_management_table-column-drop',
      this.onDropColumns,
    );
  },
  beforeUnmount() {
    if (this.refreshIntervalId) {
      clearInterval(this.refreshIntervalId);
      this.refreshIntervalId = null;
    }
  },
});
</script>

